import React, { useState, useCallback } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { ArrowRight } from "lucide-react";

// ══════════════════════════════════════════════════════════════
// Your wedding scene image
// ══════════════════════════════════════════════════════════════
const BACKGROUND_IMAGE =
  "/images/pita_Wide-angle_3D_rendered_luxury_wedding_venue_showcase_birds_eye_f75ac395-fb47-45cb-9862-8b54a5c34201.jpg";

// How close the camera zooms in
const ZOOM = 1.5;
const ZOOM_DURATION = 0.9;

// ══════════════════════════════════════════════════════════════
// Clickable zones — polygon regions over actual objects
// ══════════════════════════════════════════════════════════════
interface HeroZone {
  id: string;
  name: string;
  subtitle: string;
  clipPath: string; // CSS polygon — positions relative to the hero section
  focusPoint: { x: number; y: number };
}

const zones: HeroZone[] = [
  // ── Tables (3 visible round tables) ──
  {
    id: "table-1",
    name: "Table Covers",
    subtitle: "Gold-clothed round tables",
    clipPath: "polygon(12% 52%, 32% 48%, 38% 58%, 35% 72%, 15% 70%)",
    focusPoint: { x: 24, y: 58 },
  },
  {
    id: "table-2",
    name: "Table Covers",
    subtitle: "Gold-clothed round tables",
    clipPath: "polygon(38% 55%, 58% 52%, 62% 62%, 58% 75%, 38% 72%)",
    focusPoint: { x: 48, y: 60 },
  },
  {
    id: "table-3",
    name: "Table Covers",
    subtitle: "Gold-clothed round tables",
    clipPath: "polygon(60% 50%, 78% 48%, 80% 58%, 76% 68%, 58% 66%)",
    focusPoint: { x: 68, y: 56 },
  },

  // ── Chair Covers ──
  {
    id: "chair-1",
    name: "Chair Covers",
    subtitle: "White covers with gold sash bows",
    clipPath: "polygon(5% 65%, 18% 62%, 20% 72%, 8% 78%)",
    focusPoint: { x: 12, y: 68 },
  },
  {
    id: "chair-2",
    name: "Chair Covers",
    subtitle: "White covers with gold sash bows",
    clipPath: "polygon(28% 70%, 42% 68%, 45% 80%, 30% 82%)",
    focusPoint: { x: 35, y: 74 },
  },
  {
    id: "chair-3",
    name: "Chair Covers",
    subtitle: "White covers with gold sash bows",
    clipPath: "polygon(55% 65%, 68% 62%, 72% 72%, 58% 75%)",
    focusPoint: { x: 62, y: 68 },
  },

  // ── Chandeliers ──
  {
    id: "chandelier-1",
    name: "Chandeliers",
    subtitle: "Crystal chandeliers with warm glow",
    clipPath: "polygon(38% 8%, 55% 6%, 58% 22%, 40% 24%)",
    focusPoint: { x: 47, y: 15 },
  },
  {
    id: "chandelier-2",
    name: "Chandeliers",
    subtitle: "Crystal chandeliers with warm glow",
    clipPath: "polygon(58% 10%, 72% 8%, 74% 20%, 60% 22%)",
    focusPoint: { x: 65, y: 14 },
  },

  // ── Ceiling Drapes ──
  {
    id: "ceiling-1",
    name: "Ceiling Drapes",
    subtitle: "Flowing gold & ivory overhead drapes",
    clipPath: "polygon(8% 0%, 45% 0%, 42% 12%, 10% 14%)",
    focusPoint: { x: 25, y: 6 },
  },

  // ── Premium Fabrics ──
  {
    id: "premium-1",
    name: "Premium Fabrics",
    subtitle: "Luxurious flowing silk textures",
    clipPath: "polygon(55% 0%, 85% 0%, 82% 10%, 58% 12%)",
    focusPoint: { x: 68, y: 5 },
  },

  // ── Curtains ──
  {
    id: "curtain-1",
    name: "Curtains",
    subtitle: "Sheer floor-to-ceiling installations",
    clipPath: "polygon(78% 18%, 92% 16%, 94% 42%, 80% 44%)",
    focusPoint: { x: 86, y: 30 },
  },

  // ── Artificial Flowers ──
  {
    id: "flowers-1",
    name: "Artificial Flowers",
    subtitle: "Luxurious floral arrangements",
    clipPath: "polygon(0% 30%, 14% 28%, 16% 45%, 2% 48%)",
    focusPoint: { x: 7, y: 38 },
  },

  // ── Decor Accessories ──
  {
    id: "decor-1",
    name: "Decor Accessories",
    subtitle: "Candelabras, vases & gold accents",
    clipPath: "polygon(22% 32%, 42% 30%, 44% 44%, 24% 46%)",
    focusPoint: { x: 32, y: 38 },
  },
];

// ══════════════════════════════════════════════════════════════
// Component
// ══════════════════════════════════════════════════════════════
export default function Hero3D() {
  const [activeId, setActiveId] = useState<string | null>(null);
  const [hoveredId, setHoveredId] = useState<string | null>(null);
  const [imgLoaded, setImgLoaded] = useState(false);

  const scrollToCollections = () =>
    document.getElementById("collections")?.scrollIntoView({ behavior: "smooth" });

  const activeZone = activeId !== null ? zones.find((z) => z.id === activeId) : null;
  const isZoomed = activeId !== null;

  const handleZoneClick = useCallback((id: string, e: React.MouseEvent) => {
    e.stopPropagation(); // prevent background click
    setActiveId((prev) => (prev === id ? null : id));
  }, []);

  const handleZoneHover = useCallback((id: string) => setHoveredId(id), []);
  const handleZoneLeave = useCallback(() => setHoveredId(null), []);
  const handleBgClick = useCallback(() => setActiveId(null), []);

  // Background zoom origin
  const bgOriginX = activeZone ? activeZone.focusPoint.x : 50;
  const bgOriginY = activeZone ? activeZone.focusPoint.y : 50;

  // Label placement
  const labelSide = (fp: { x: number }) => (fp.x > 60 ? "right" : "left");

  return (
    <section id="top" className="relative min-h-screen overflow-hidden select-none">
      {/* ── Loading skeleton ── */}
      {!imgLoaded && (
        <div className="absolute inset-0 bg-gradient-to-br from-amber-900 via-amber-800 to-gray-900 flex items-center justify-center z-50">
          <div className="text-center">
            <div className="w-14 h-14 border-4 border-amber-400 border-t-transparent rounded-full animate-spin mx-auto mb-3" />
            <p className="text-amber-400/80 text-sm tracking-wide">Loading experience…</p>
          </div>
        </div>
      )}

      {/* ── Background image — normal position, fills section ── */}
      <div
        className="absolute inset-0"
        style={{
          backgroundImage: `url('${BACKGROUND_IMAGE}')`,
          backgroundSize: "cover",
          backgroundPosition: "center",
          transform: isZoomed ? `scale(${ZOOM})` : "scale(1)",
          transformOrigin: `${bgOriginX}% ${bgOriginY}%`,
          transition: `transform ${ZOOM_DURATION}s cubic-bezier(0.25, 0.46, 0.45, 0.94)`,
          willChange: "transform",
        }}
      />
      <img
        src={BACKGROUND_IMAGE}
        alt=""
        className="hidden"
        onLoad={() => setImgLoaded(true)}
      />

      {/* ── Dark overlay — fades during zoom ── */}
      <div
        className="absolute inset-0 pointer-events-none"
        style={{
          background:
            "linear-gradient(to bottom, rgba(0,0,0,0.65) 0%, rgba(0,0,0,0.25) 45%, rgba(0,0,0,0.7) 100%)",
          opacity: isZoomed ? 0.15 : 1,
          transition: "opacity 0.7s ease",
        }}
      />

      {/* ── Vignette ── */}
      <div
        className="absolute inset-0 pointer-events-none"
        style={{
          background:
            "radial-gradient(ellipse at center, transparent 40%, rgba(0,0,0,0.65) 100%)",
          opacity: isZoomed ? 0.85 : 0.45,
          transition: "opacity 0.7s ease",
        }}
      />

      {/* ── Radial warm glow at zoom focus ── */}
      <div
        className="absolute inset-0 pointer-events-none z-10"
        style={{
          background:
            isZoomed && activeZone
              ? `radial-gradient(ellipse 40% 40% at ${activeZone.focusPoint.x}% ${activeZone.focusPoint.y}%, rgba(212,175,55,0.18), transparent 70%)`
              : "none",
          transition: "opacity 0.6s ease",
          opacity: isZoomed ? 1 : 0,
        }}
      />

      {/* ── Clickable zone layer ── */}
      <div className="absolute inset-0 z-20">
        {zones.map((zone) => {
          const isActive = activeId === zone.id;
          const isHovered = hoveredId === zone.id;
          const dimmed = isZoomed && !isActive;

          return (
            <div
              key={zone.id}
              className="absolute inset-0"
              style={{
                clipPath: zone.clipPath,
                cursor: "pointer",
              }}
              onClick={(e) => handleZoneClick(zone.id, e)}
              onMouseEnter={() => handleZoneHover(zone.id)}
              onMouseLeave={handleZoneLeave}
              role="button"
              tabIndex={0}
              aria-label={zone.name}
              onKeyDown={(e) => {
                if (e.key === "Enter" || e.key === " ") {
                  e.preventDefault();
                  setActiveId((prev) => (prev === zone.id ? null : zone.id));
                }
              }}
            >
              {/* Hover/active fill + glow — applied inside the clipped zone */}
              <div
                className="absolute inset-0 pointer-events-none"
                style={{
                  backgroundColor: isActive
                    ? "rgba(212,175,55,0.18)"
                    : isHovered
                    ? "rgba(212,175,55,0.1)"
                    : "transparent",
                  transition: "background-color 0.3s ease",
                }}
              />

              {/* SVG polygon outline — shows on hover/active */}
              <svg
                className="absolute inset-0 w-full h-full pointer-events-none"
                viewBox="0 0 100 100"
                preserveAspectRatio="none"
                style={{
                  filter:
                    isActive
                      ? "drop-shadow(0 0 15px rgba(212,175,55,0.7))"
                      : isHovered
                      ? "drop-shadow(0 0 10px rgba(212,175,55,0.5))"
                      : "none",
                  transition: "filter 0.4s ease",
                }}
              >
                <polygon
                  points={zone.points}
                  fill={
                    isActive
                      ? "rgba(212,175,55,0.1)"
                      : isHovered
                      ? "rgba(212,175,55,0.06)"
                      : "transparent"
                  }
                  stroke={
                    isActive
                      ? "rgba(212,175,55,0.8)"
                      : isHovered
                      ? "rgba(212,175,55,0.6)"
                      : "transparent"
                  }
                  strokeWidth={isActive ? "0.5" : "0.3"}
                  style={{ transition: "fill 0.3s ease, stroke 0.3s ease" }}
                />
              </svg>
            </div>
          );
        })}

        {/* ── Label card for active zone ── */}
        <AnimatePresence>
          {activeZone && (
            <motion.div
              key={activeZone.id}
              initial={{ opacity: 0, scale: 0.88, y: 8 }}
              animate={{ opacity: 1, scale: 1, y: 0 }}
              exit={{ opacity: 0, scale: 0.88, y: 8 }}
              transition={{ duration: 0.35, ease: [0.25, 0.46, 0.45, 0.94] }}
              className="absolute z-50 pointer-events-auto"
              style={{
                top: `${activeZone.focusPoint.y}%`,
                left: `${activeZone.focusPoint.x}%`,
                transform: "translate(-50%, -50%)",
              }}
            >
              <div
                className={`relative whitespace-nowrap ${
                  labelSide(activeZone.focusPoint) === "right"
                    ? "ml-8"
                    : "-ml-8 -translate-x-full"
                }`}
              >
                {/* Connector line */}
                <div
                  className={`absolute top-1/2 -translate-y-1/2 w-6 h-[2px] bg-gradient-to-r ${
                    labelSide(activeZone.focusPoint) === "right"
                      ? "left-full from-amber-400 to-transparent"
                      : "right-full from-transparent to-amber-400"
                  }`}
                />

                <div className="relative bg-gradient-to-br from-white/95 via-amber-50/90 to-white/95 backdrop-blur-xl rounded-2xl px-6 py-4 shadow-2xl shadow-black/40 border border-amber-300/30">
                  {/* Gold accent bar */}
                  <div
                    className={`absolute top-3 bottom-3 w-1 rounded-full bg-gradient-to-b from-amber-400 via-amber-500 to-amber-400 ${
                      labelSide(activeZone.focusPoint) === "right"
                        ? "-right-1"
                        : "-left-1"
                    }`}
                  />

                  <h3 className="text-amber-800 font-bold text-base md:text-lg mb-0.5 leading-tight">
                    {activeZone.name}
                  </h3>
                  <p className="text-gray-500 text-xs md:text-sm mb-2.5 leading-snug">
                    {activeZone.subtitle}
                  </p>
                  <button
                    onClick={(e) => {
                      e.stopPropagation();
                      scrollToCollections();
                    }}
                    className="text-xs text-amber-600 hover:text-amber-900 flex items-center gap-1.5 font-semibold transition-all duration-300 hover:gap-3"
                  >
                    View Collection
                    <ArrowRight size={12} className="transition-transform group-hover:translate-x-1" />
                  </button>
                </div>
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </div>

      {/* ── Floating golden particles ── */}
      <div className="absolute inset-0 overflow-hidden pointer-events-none z-10">
        {[...Array(22)].map((_, i) => {
          const size = 1 + (i % 3) * 0.5;
          return (
            <motion.div
              key={i}
              className="absolute rounded-full"
              style={{
                width: size,
                height: size,
                left: `${4 + ((i * 4.7) % 92)}%`,
                top: `${6 + ((i * 6.3) % 88)}%`,
                background: `rgba(212, 175, 55, ${0.3 + (i % 4) * 0.12})`,
              }}
              animate={{
                y: [0, -(50 + (i % 5) * 20), 0],
                x: [0, Math.sin(i * 0.7) * 18, 0],
                opacity: [0, 0.6 + (i % 3) * 0.15, 0],
                scale: [0, 1, 0],
              }}
              transition={{
                duration: 3.5 + (i % 5) * 0.8,
                repeat: Infinity,
                delay: i * 0.28,
                ease: "easeInOut",
              }}
            />
          );
        })}
      </div>

      {/* ── Instruction tooltip ── */}
      <AnimatePresence>
        {!isZoomed && (
          <motion.div
            key="tooltip"
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: 10 }}
            transition={{ delay: 2.5, duration: 0.6 }}
            className="absolute bottom-28 left-1/2 -translate-x-1/2 z-30"
          >
            <motion.div
              className="bg-white/10 backdrop-blur-md rounded-full px-5 py-2.5 border border-white/15"
              animate={{ y: [0, 6, 0] }}
              transition={{ duration: 2.8, repeat: Infinity, ease: "easeInOut" }}
            >
              <p className="text-white/85 text-sm flex items-center gap-2">
                <motion.span
                  className="w-2.5 h-2.5 bg-amber-400 rounded-full inline-block"
                  animate={{ scale: [1, 1.5, 1], opacity: [1, 0.5, 1] }}
                  transition={{ duration: 1.5, repeat: Infinity }}
                />
                Click on highlighted areas to explore products
              </p>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* ── Bottom gradient fade ── */}
      <div className="absolute bottom-0 left-0 right-0 h-32 md:h-40 bg-gradient-to-t from-[#fdf6eb] to-transparent pointer-events-none z-40" />
    </section>
  );
}
